'use strict';
// Observation tools share the live simulation; camera state never changes saves.
let followedId=null,observatoryFilter='all',miniLast=-Infinity,miniEpoch=-1,miniTerrain=null;
const premiumOld={frame:runSmoothFrame,selection:showSelection,newWorld,restore};
function daylightAt(hour){const night=(1-Math.cos((hour-12)*Math.PI/12))/2;return {night:Math.max(0,Math.min(.48,(night-.4)*.8)),dawn:Math.max(0,1-Math.abs(hour-6.5)/1.5)*.10,dusk:Math.max(0,1-Math.abs(hour-18)/2)*.12};}
function paintDaylight(){const c=readCalendar(),light=daylightAt(c.hour+c.minute/60);ctx.save();ctx.fillStyle='rgba(5,15,40,'+light.night+')';ctx.fillRect(0,0,cw,ch);if(light.dawn+light.dusk>0){ctx.fillStyle='rgba(246,157,82,'+(light.dawn+light.dusk)+')';ctx.fillRect(0,0,cw,ch);}if(light.night>.15){const s=base*zoom,ox=(cw-W*s)/2+panX,oy=(ch-H*s)/2+panY;for(const h of houses){const x=ox+h.x*s,y=oy+h.y*s;if(x<-40||y<-40||x>cw+40||y>ch+40)continue;const radius=Math.max(8,s*2.2),glow=ctx.createRadialGradient(x,y,0,x,y,radius);glow.addColorStop(0,'rgba(255,195,93,.22)');glow.addColorStop(1,'rgba(255,195,93,0)');ctx.fillStyle=glow;ctx.fillRect(x-radius,y-radius,radius*2,radius*2);}}ctx.restore();}
function cameraTo(x,y){const s=base*zoom;panX=(W/2-Math.max(0,Math.min(W,x)))*s;panY=(H/2-Math.max(0,Math.min(H,y)))*s;}
function stopFollowing(){followedId=null;$('follow-strip').hidden=true;}
function followResident(id){const e=entities.find(e=>e.id===Number(id));if(!e)return false;followedId=e.id;selectedId=e.id;zoom=Math.max(zoom,2);$('zoom-label').textContent=Math.round(zoom*100)+'%';cameraTo(e.x,e.y);showSelection(e.id);$('follow-strip').hidden=false;$('follow-name').textContent=e.name;$('observatory').close();return true;}
function mapViewport(){const s=base*zoom;return{x:W/2-panX/s-cw/(2*s),y:H/2-panY/s-ch/(2*s),width:cw/s,height:ch/s};}
function paintMinimap(now){if(now-miniLast<250)return;miniLast=now;const c=$('world-mini').getContext('2d');if(!miniTerrain||miniEpoch!==terrainEpoch||now-(miniTerrain.updated||0)>1500){miniTerrain??=document.createElement('canvas');miniTerrain.width=W;miniTerrain.height=H;const t=miniTerrain.getContext('2d');for(let i=0;i<N;i++){t.fillStyle=typeof terrainColorAt==='function'?terrainColorAt(i%W,Math.floor(i/W),grid[i]):colors[grid[i].t];t.fillRect(i%W,Math.floor(i/W),1,1);}miniTerrain.updated=now;miniEpoch=terrainEpoch;}c.clearRect(0,0,W,H);c.drawImage(miniTerrain,0,0);for(const v of villages){c.fillStyle=v.color;c.fillRect(v.x-1,v.y-1,2,2);}for(const e of humans())if(e.destiny?.chosen){c.fillStyle='#ffe6a0';c.fillRect(e.x-1,e.y-1,2,2);}if(followedId!==null){const e=entities.find(e=>e.id===followedId);if(e){c.strokeStyle='#fff';c.strokeRect(e.x-2,e.y-2,4,4);}}const r=mapViewport();c.strokeStyle='#ffffff';c.lineWidth=.8;c.strokeRect(r.x,r.y,r.width,r.height);}
function worldOverview(){const residents=humans(),kings=new Set(kingdoms.map(k=>k.king));return{population:residents.length,animals:entities.length-residents.length,kingdoms:kingdoms.filter(k=>residents.some(e=>kingdomOf(e)===k.id)).length,wars:wars.length,heroes:residents.filter(e=>e.destiny?.chosen).length,hungry:residents.filter(e=>e.hunger<35).length,thirsty:residents.filter(e=>e.thirst<35).length,kings,residents};}
function renderObservatory(){const data=worldOverview(),box=$('overview-stats');box.replaceChildren();for(const [label,value] of [['Cư dân',data.population],['Vương quốc',data.kingdoms],['Chiến tranh',data.wars],['Anh hùng',data.heroes],['Đang đói',data.hungry],['Đang khát',data.thirsty]]){const tile=document.createElement('div'),b=document.createElement('b'),small=document.createElement('span');b.textContent=value;small.textContent=label;tile.append(b,small);box.append(tile);}const list=$('resident-list');list.replaceChildren();const search=$('resident-search').value.trim().toLocaleLowerCase('vi');const filtered=data.residents.filter(e=>(observatoryFilter==='all'||observatoryFilter==='heroes'&&e.destiny?.chosen||observatoryFilter==='kings'&&data.kings.has(e.id)||observatoryFilter==='needs'&&(e.hunger<35||e.thirst<35||e.hp<40))&&(!search||(e.name+' '+raceNames[e.race]).toLocaleLowerCase('vi').includes(search)));for(const e of filtered){const row=document.createElement('article'),body=document.createElement('div'),name=document.createElement('b'),detail=document.createElement('small'),b=document.createElement('button');name.textContent=(data.kings.has(e.id)?'♛ ':e.destiny?.chosen?'★ ':'')+e.name;detail.textContent=raceNames[e.race]+' · '+(jobNames[e.job]||'Cư dân')+' · Sức khỏe '+Math.round(e.hp)+'%'+(e.hunger<35?' · Đói':'')+(e.thirst<35?' · Khát':'');b.textContent='Theo dõi';b.onclick=()=>followResident(e.id);body.append(name,detail);row.append(body,b);list.append(row);}if(!filtered.length)list.textContent='Không có cư dân phù hợp.';$('resident-count').textContent=filtered.length+' cư dân';}
function buildObservationUI(){const top=document.createElement('button');top.id='overview-open';top.textContent='◉ Tổng quan';$('help').before(top);const shell=document.createElement('div');shell.id='mini-shell';const title=document.createElement('span');title.textContent='BẢN ĐỒ NHỎ';const mini=document.createElement('canvas');mini.id='world-mini';mini.width=W;mini.height=H;mini.setAttribute('aria-label','Bản đồ nhỏ: chạm hoặc kéo để di chuyển góc nhìn');const hide=document.createElement('button');hide.textContent='−';hide.setAttribute('aria-label','Ẩn hoặc hiện bản đồ nhỏ');hide.onclick=()=>{mini.hidden=!mini.hidden;hide.textContent=mini.hidden?'+':'−';};shell.append(title,hide,mini);$('viewport').append(shell);const strip=document.createElement('div');strip.id='follow-strip';strip.hidden=true;const name=document.createElement('span');name.id='follow-name';const stop=document.createElement('button');stop.textContent='Dừng theo dõi';stop.onclick=stopFollowing;strip.append(name,stop);$('viewport').append(strip);
const dialog=document.createElement('dialog');dialog.id='observatory';dialog.className='wide-dialog';const close=document.createElement('button');close.className='close';close.textContent='×';close.setAttribute('aria-label','Đóng');close.onclick=()=>dialog.close();const heading=document.createElement('h2');heading.textContent='Quan sát thế giới';const stats=document.createElement('div');stats.id='overview-stats';const controls=document.createElement('div');controls.className='observer-controls';const search=document.createElement('input');search.id='resident-search';search.placeholder='Tìm tên hoặc tộc người';search.setAttribute('aria-label','Tìm cư dân');search.maxLength=50;search.oninput=renderObservatory;const filter=document.createElement('select');filter.setAttribute('aria-label','Lọc cư dân');for(const [value,text] of [['all','Tất cả cư dân'],['heroes','★ Anh hùng'],['kings','♛ Nhà vua'],['needs','Cần trợ giúp']]){const o=document.createElement('option');o.value=value;o.textContent=text;filter.append(o);}filter.onchange=()=>{observatoryFilter=filter.value;renderObservatory();};const count=document.createElement('p');count.id='resident-count';const list=document.createElement('div');list.id='resident-list';controls.append(search,filter);dialog.append(close,heading,stats,controls,count,list);document.body.append(dialog);top.onclick=()=>{renderObservatory();dialog.showModal();};let miniDrag=null;const jump=e=>{const rect=mini.getBoundingClientRect();stopFollowing();cameraTo((e.clientX-rect.left)/rect.width*W,(e.clientY-rect.top)/rect.height*H);miniLast=-Infinity;};mini.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();miniDrag=e.pointerId;mini.setPointerCapture(e.pointerId);jump(e);};mini.onpointermove=e=>{if(miniDrag===e.pointerId)jump(e);};mini.onpointerup=mini.onpointercancel=mini.onlostpointercapture=()=>{miniDrag=null;};canvas.addEventListener('pointerdown',e=>{if(e.button===2||tool==='hand'||e.pointerType==='touch')stopFollowing();},true);$('fit').addEventListener('click',stopFollowing);}
buildObservationUI();
showSelection=function(id){premiumOld.selection(id);const e=entities.find(e=>e.id===id);if(!e||$('selection').hidden)return;const button=document.createElement('button');button.className='follow-action';button.textContent=followedId===id?'Dừng theo dõi':'◉ Theo dõi trên bản đồ';button.onclick=()=>followedId===id?stopFollowing():followResident(id);$('selection').append(button);};
runSmoothFrame=function(now){if(followedId!==null){const e=entities.find(e=>e.id===followedId);if(e){cameraTo(e.x,e.y);$('follow-name').textContent=e.name;}else{stopFollowing();toast('Sinh vật được theo dõi đã qua đời.');}}premiumOld.frame(now);paintMinimap(now);};
newWorld=function(...args){premiumOld.newWorld(...args);stopFollowing();miniEpoch=-1;miniLast=-Infinity;};
restore=function(data){premiumOld.restore(data);stopFollowing();miniEpoch=-1;miniLast=-Infinity;};
window.mamWorld={...window.mamWorld,newWorld:(...a)=>newWorld(...a),restore:d=>restore(d),followResident,stopFollowing,getObservation:()=>{const d=worldOverview();return{population:d.population,kingdoms:d.kingdoms,wars:d.wars,heroes:d.heroes,hungry:d.hungry,thirsty:d.thirsty,followedId};}};
